-- OCG-W W7: one-step tier promotion (TencentDB-style S0->S3 semantics) with the OCG P3 guard.
-- A promotion is a NEW pending item plus a pending PROMOTED_FROM edge (src = promoted item, dst = source item).
-- The source item is never replaced or closed. The promoted item keeps the source's kind, room, valid_from,
-- valid_until and source_message_id, so promotion is never date-lossy (hallaon-ocg b3 RESULTS, P3).
-- Each trigger is one line because the local harness splits migration files on a semicolon followed by a newline.
CREATE TRIGGER memory_edges_promotion_shape BEFORE INSERT ON memory_edges WHEN NEW.type='PROMOTED_FROM' AND NOT EXISTS (SELECT 1 FROM memory_items n JOIN memory_items o ON o.id=NEW.dst_id WHERE n.id=NEW.src_id AND n.room_id=o.room_id AND n.kind=o.kind AND n.tier=o.tier+1 AND (n.tier<3 OR n.kind='skill') AND n.valid_from=o.valid_from AND n.valid_until IS o.valid_until AND n.source_message_id=o.source_message_id AND n.review_state='pending' AND o.review_state='approved' AND n.proposed_by=NEW.proposed_by) BEGIN SELECT RAISE(ABORT,'promotion must be one tier up from an approved item and keep its kind, room, validity window and source'); END;
CREATE TRIGGER memory_edges_promotion_single BEFORE INSERT ON memory_edges WHEN NEW.type='PROMOTED_FROM' AND EXISTS (SELECT 1 FROM memory_edges e WHERE e.type='PROMOTED_FROM' AND (e.src_id=NEW.src_id OR e.dst_id=NEW.dst_id) AND e.review_state IN ('pending','approved')) BEGIN SELECT RAISE(ABORT,'item already has an open promotion'); END;
CREATE TRIGGER memory_items_promotion_order BEFORE UPDATE ON memory_items WHEN NEW.review_state='approved' AND OLD.review_state='pending' AND EXISTS (SELECT 1 FROM memory_edges e WHERE e.src_id=OLD.id AND e.type='PROMOTED_FROM') AND NOT EXISTS (SELECT 1 FROM memory_edges e WHERE e.src_id=OLD.id AND e.type='PROMOTED_FROM' AND e.review_state='approved') BEGIN SELECT RAISE(ABORT,'approve the PROMOTED_FROM edge before the promoted item'); END;
CREATE TRIGGER memory_items_frozen BEFORE UPDATE ON memory_items WHEN NEW.id IS NOT OLD.id OR NEW.room_id IS NOT OLD.room_id OR NEW.kind IS NOT OLD.kind OR NEW.tier IS NOT OLD.tier OR NEW.title IS NOT OLD.title OR NEW.body IS NOT OLD.body OR NEW.source_message_id IS NOT OLD.source_message_id OR NEW.proposed_by IS NOT OLD.proposed_by OR NEW.valid_from IS NOT OLD.valid_from OR NEW.created_at IS NOT OLD.created_at OR (OLD.valid_until IS NOT NULL AND NEW.valid_until IS NOT OLD.valid_until) BEGIN SELECT RAISE(ABORT,'memory item content is immutable; propose a new item and supersede'); END;
CREATE TRIGGER memory_edges_frozen BEFORE UPDATE ON memory_edges WHEN NEW.id IS NOT OLD.id OR NEW.src_id IS NOT OLD.src_id OR NEW.dst_id IS NOT OLD.dst_id OR NEW.type IS NOT OLD.type OR NEW.proposed_by IS NOT OLD.proposed_by OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'memory edge is immutable'); END;
CREATE TRIGGER memory_items_no_delete BEFORE DELETE ON memory_items BEGIN SELECT RAISE(ABORT,'memory items are append-only'); END;
CREATE TRIGGER memory_edges_no_delete BEFORE DELETE ON memory_edges BEGIN SELECT RAISE(ABORT,'memory edges are append-only'); END;
